// ANCHOR: example
//! This example builds, serializes, and reads a Cap'n Proto message with code
//! generated by `capnpc` from `foo.capnp`.
//!
//! `build.rs` regenerates the checked-in `foo_capnp.rs` when the external
//! `capnp` compiler is available. Builds without that compiler use the checked-
//! in generated source, so the example still compiles in CI.
//!
//! A standalone crate needs these dependencies:
//! ```toml
//! [dependencies]
//! capnp = "0.25.6"
//! [build-dependencies]
//! capnpc = "0.25.3"
//! ```
//!
//! Install the Cap'n Proto compiler to regenerate code from the schema.
//! `capnpc` is a Rust code-generation plugin; it does not include the compiler.
//! The repository build script falls back to the checked-in generated file.
//! A standalone `build.rs` can compile the schema like this:
//! ```rust
//! fn main() {
//!     capnpc::CompilerCommand::new()
//!         .src_prefix("examples/binary_encoders")
//!         .file("examples/binary_encoders/foo.capnp")
//!         .run()
//!         .expect("schema compiler command");
//! }
//! ```

use capnp::message::Builder;
use capnp::message::ReaderOptions;
use capnp::serialize;

/// Define the module for the generated code.
#[allow(
    clippy::all,
    clippy::pedantic,
    clippy::nursery,
    reason = "generated code"
)]
pub mod foo_capnp {
    // The `capnpc` compiler generates a file named [filename]_capnp.rs.
    include!(concat!(env!("OUT_DIR"), "/foo_capnp.rs"));
}

/// Builds, serializes, and reads a Cap'n Proto message.
fn main() -> anyhow::Result<()> {
    // 1. Create a message builder (the container for the data).
    let mut message = Builder::new_default();

    {
        // 2. Initialize the root object using the generated Builder type for
        //    'MyStruct'.
        let mut my_struct =
            message.init_root::<foo_capnp::my_struct::Builder>();

        // 3. Set values on the fields.
        my_struct.set_name("Hello from Rust");
        my_struct.set_value(42);
    }

    // 4. Serialize the message into a byte buffer.
    let mut write_buffer = Vec::new();
    serialize::write_message(&mut write_buffer, &message)?;

    // 5. Read the message back and verify its fields.
    let mut cursor = std::io::Cursor::new(write_buffer.as_slice());
    let reader = serialize::read_message(&mut cursor, ReaderOptions::new())?;
    let decoded = reader.get_root::<foo_capnp::my_struct::Reader>()?;
    assert_eq!(decoded.get_name()?, "Hello from Rust");
    assert_eq!(decoded.get_value(), 42);

    println!(
        "Cap'n Proto message serialized. Size: {} bytes",
        write_buffer.len()
    );
    Ok(())
}

// ANCHOR_END: example

/// Entry point to run the Cap'n Proto example.
pub fn run() -> anyhow::Result<()> {
    main()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn capnp_round_trip_preserves_the_message() -> anyhow::Result<()> {
        main()
    }

    /// Reading a message that is cut short must fail rather than panic.
    #[test]
    fn truncated_message_is_an_error() -> anyhow::Result<()> {
        let mut message = Builder::new_default();
        message
            .init_root::<foo_capnp::my_struct::Builder>()
            .set_value(7);
        let mut bytes = Vec::new();
        serialize::write_message(&mut bytes, &message)?;

        let mut cursor = std::io::Cursor::new(&bytes[..bytes.len() - 4]);
        assert!(
            serialize::read_message(&mut cursor, ReaderOptions::new()).is_err()
        );
        Ok(())
    }

    /// Unset fields read back as the schema default.
    #[test]
    fn unset_fields_read_back_as_defaults() -> anyhow::Result<()> {
        let mut message = Builder::new_default();
        message.init_root::<foo_capnp::my_struct::Builder>();
        let reader =
            message.get_root_as_reader::<foo_capnp::my_struct::Reader>()?;
        assert_eq!(reader.get_name()?, "");
        assert_eq!(reader.get_value(), 0);
        Ok(())
    }
}
